public void processData(Collection<String> items) {
    // Polymorphic processing using the Collection interface
    for (String item : items) {
        System.out.println(item);
    }
}

// Usage with different implementations
List<String> list = new ArrayList<>(List.of("A", "B"));
Set<String> set = new HashSet<>(Set.of("C", "D"));
processData(list);
processData(set);
